/**
 * What went wrong, in words a person can act on.
 */
public 
enum DiffuseError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * A file, a flow or an edit that could not be done.
     */
    case Failed(message: String
    )
    /**
     * The gateway or forge: `kind` is `unreachable`, `key`, `offline`,
     * `invalid`, `server`, `unreadable` or `lost`.
     */
    case Gateway(kind: String, message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

#if compiler(>=6)
extension DiffuseError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDiffuseError: FfiConverterRustBuffer {
    typealias SwiftType = DiffuseError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DiffuseError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Failed(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Gateway(
            kind: try FfiConverterString.read(from: &buf), 
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DiffuseError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Failed(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Gateway(kind,message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(kind, into: &buf)
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


